{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{#- Orden de manufactura de UN taller, como PDF aparte.

    La orden de compra (lo que se le encarga y lo que se le paga) y la ficha de
    manufactura (cómo se hace la prenda) se imprimen por separado: son dos cosas
    distintas y no siempre se mandan juntas -- si cambia la ficha se reenvía sola,
    sin volver a mandar la orden. "Orden de Maquila" trae la orden; esta, la ficha.

    El contenido lo arma al momento om_general.om_de_oc (método jinja registrado en
    hooks.py): un registro por producto que trabaja ESE taller, con la info general
    y las tallas completas y solo lo que se le asignó en "Para". Así nunca se
    desincroniza de la ficha general del costeo. -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Orden de manufactura") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}

{{ oc.encabezado(doc, "Orden de Manufactura", true) }}

{#- Orden de manufactura de ESTE taller: un registro por producto que trabaja, con la
    info general y tallas completas y solo lo que se le asignó en la OM general del
    costeo (om_general.om_de_oc, registrado como método jinja en hooks.py). -#}
{%- set oms = om_de_oc(doc.name) | selectattr("origen", "equalto", "general") | list -%}
{%- set campos = [("om_modelo", "Modelo"), ("om_tela", "Tela"), ("om_color", "Color"),
      ("om_color_principal", "Color principal"), ("om_forro", "Forro"), ("om_combinacion", "Combinación"),
      ("om_ubicacion", "Ubicación de aplicaciones"), ("om_aberturas", "Aberturas"), ("om_fecha_requerida", "Fecha requerida")] -%}
{%- for r in oms %}
<div{% if not loop.first %} style="page-break-before: always;"{% endif %}>
    {{ oc.seccion("Ficha de manufactura · " ~ (r.item_name or r.producto)) }}
    {%- set llenos = [] -%}
    {%- for f, l in campos -%}{%- if r.general.get(f) -%}{%- set _ = llenos.append((l, r.general.get(f))) -%}{%- endif -%}{%- endfor %}
    <table class="yk-ficha">
        {%- for fila in llenos | batch(2) %}
        <tr>
            {%- for l, v in fila %}
            <td class="k">{{ l }}</td><td class="v">{{ fecha_corta(v) if l == "Fecha requerida" else v }}</td>
            {%- endfor %}
            {%- if fila | length == 1 %}<td class="k"></td><td class="v"></td>{% endif %}
        </tr>
        {%- endfor %}
    </table>
    {%- set marcas = [] -%}
    {%- for f, l in [("om_bordado", "Bordado"), ("om_estampado", "Estampado"), ("om_sublimado", "Sublimado"), ("om_reflejante", "Reflejante")] -%}
        {%- if r.general.get(f) -%}{%- set _ = marcas.append(l) -%}{%- endif -%}
    {%- endfor %}
    {%- if marcas %}
    <div class="yk-lleva"><span class="k">Lleva</span>{% for m in marcas %}<span class="yk-tag">{{ m }}</span>{% endfor %}</div>
    {%- endif %}

    {%- if r.tallas %}
    {{ oc.seccion("Tallas") }}
    <table class="items-table">
        <thead><tr><th>Producto</th><th style="width:30mm">Género</th><th style="width:24mm">Talla</th><th class="text-right" style="width:26mm">Cantidad</th></tr></thead>
        <tbody>
        {%- for t in r.tallas %}
            <tr><td class="muted">{{ t.producto or r.producto }}</td><td>{{ t.genero or "—" }}</td><td><b>{{ t.talla }}</b></td><td class="num">{{ "{:,.0f}".format(t.cantidad or 0) }}</td></tr>
        {%- endfor %}
            <tr><td colspan="3" class="text-right"><b>Total</b></td><td class="num"><b>{{ "{:,.0f}".format(r.tallas | sum(attribute="cantidad")) }}</b></td></tr>
        </tbody>
    </table>
    {%- endif %}

    {%- if r.procesos %}
    {{ oc.seccion("Procesos") }}
    <table class="items-table">
        <thead><tr><th style="width:6mm">#</th><th style="width:42mm">Proceso</th><th>Ubicación e indicaciones</th><th style="width:40mm">Colores</th></tr></thead>
        <tbody>
        {%- for p in r.procesos %}
            <tr><td class="muted">{{ loop.index }}</td><td><b>{{ p.nombre_proceso or "" }}</b></td><td>{{ p.ubicacion or "" }}</td><td class="muted">{{ p.colores or "" }}</td></tr>
        {%- endfor %}
        </tbody>
    </table>
    {%- endif %}

    {%- for t in r.tablas %}
    {{ oc.seccion(t.name ~ ((" (" ~ t.unit ~ ")") if t.unit else "")) }}
    {#- La primera fila de la tabla se toma como encabezado. -#}
    <table class="items-table yk-flex">
        {%- if t.rows %}
        <thead><tr>{% for c in t.columns %}<th{% if not loop.first %} class="text-center"{% endif %}>{{ t.rows[0].cells.get(c, "") }}</th>{% endfor %}</tr></thead>
        {%- endif %}
        <tbody>
        {%- for row in t.rows[1:] %}
            <tr>{% for c in t.columns %}<td{% if loop.first %} class="k"{% else %} class="text-center"{% endif %}>{{ row.cells.get(c, "") }}</td>{% endfor %}</tr>
        {%- endfor %}
        </tbody>
    </table>
    {%- endfor %}

    {%- if r.observaciones %}
    <div class="yk-notas">
        <span class="yk-lbl">Observaciones</span>
        <ol class="terms-content" style="margin:0; padding-left:4.5mm;">
        {%- for o in r.observaciones %}<li style="white-space: pre-line;">{{ o.texto }}</li>{%- endfor %}
        </ol>
    </div>
    {%- endif %}

    {%- set imagenes = [] -%}{%- set otros = [] -%}
    {%- for a in r.archivos -%}
        {%- set ext = (a.archivo or "").split("?")[0].split(".")[-1] | lower -%}
        {%- if ext in ["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg"] %}{% set _ = imagenes.append(a) %}{% else %}{% set _ = otros.append(a) %}{% endif -%}
    {%- endfor %}
    {%- if imagenes %}
    {{ oc.seccion("Diagramas y referencias") }}
    <table class="yk-galeria">
        {%- for par in imagenes | batch(2) %}
        <tr>
            {%- for a in par %}
            <td><div class="img"><img src="{{ a.archivo }}" alt=""></div>{% if a.descripcion %}<div class="pie">{{ a.descripcion }}</div>{% endif %}</td>
            {%- endfor %}
            {%- if par | length == 1 %}<td></td>{% endif %}
        </tr>
        {%- endfor %}
    </table>
    {%- endif %}
    {%- for a in otros %}<div class="item-code">Archivo adjunto: {{ a.descripcion or a.archivo }}</div>{%- endfor %}
</div>
{%- endfor %}

{%- if not oms %}
<p class="muted">Este taller no tiene ficha de manufactura capturada todavía.</p>
{%- endif %}

{{ oc.firmas(doc) }}
{{ oc.pie() }}

</div>

{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
